 if($data['nome']===''||$data['telefone']===''||$data['logradouro']===''||$data['numero']===''||$data['bairro']===''||$data['cidade']===''||$data['forma_pagamento']==='') $erro='Preencha nome, telefone, endereço, número, bairro, cidade e forma de pagamento.';
 elseif(!in_array($data['forma_pagamento'],['Pix','Dinheiro','Cartão na entrega'],true)) $erro='Selecione uma forma de pagamento válida.';
