?><!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dados de entrega | Pastelaria OTA</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><style>body{background:#f5f5f5;color:#333;font-family:Arial,sans-serif}.container{max-width:1150px}.hero,.panel{border-radius:14px;padding:24px}.hero{background:#333;color:#fff}.hero i,.heading i{color:#ffc107}.panel{background:#fff;border:1px solid #e7e7e7;box-shadow:0 5px 16px #00000008}.heading{font-weight:800;color:#e21b23}.form-label{font-weight:700;font-size:.9rem}.form-control,.form-select{min-height:44px}.btnota{background:#e21b23;color:#fff;border:0;border-radius:8px;padding:12px 18px;text-decoration:none;font-weight:bold;display:inline-block}.btnota:hover{background:#bd1018;color:white}.back{color:#333;text-decoration:none;font-weight:bold}.total{color:#e21b23;font-size:1.3rem;font-weight:800}</style></head><body><main class="container py-4 py-md-5"><a class="back" href="carrinho.php"><i class="bi bi-arrow-left"></i> Voltar ao carrinho</a><div class="hero mt-3 mb-4"><h1><i class="bi bi-geo-alt-fill"></i> Dados de entrega</h1><p class="mb-0">Informe os dados para receber seu pedido da OTA.</p></div><?php if($erro): ?><div class="alert alert-danger"><?=ota_escape($erro)?></div><?php endif; ?><form method="post" class="row g-4"><div class="col-lg-8"><section class="panel"><h2 class="h4 fw-bold mb-4">Informações para entrega</h2><div class="row g-3"><?php $fields=[['nome','Nome completo','text',12,true],['email','E-mail','email',6,false],['telefone','Telefone','tel',6,true],['cep','CEP','text',4,false],['logradouro','Rua ou avenida','text',8,true],['numero','Número','text',4,true],['complemento','Complemento','text',8,false],['bairro','Bairro','text',6,true],['cidade','Cidade','text',6,true],['estado','Estado (UF)','text',3,false],['referencia','Ponto de referência','text',9,false]]; foreach($fields as [$name,$label,$type,$width,$required]): ?><div class="col-md-<?=$width?>"><label class="form-label" for="<?=$name?>"><?=$label?><?=$required?' *':''?></label><input class="form-control" id="<?=$name?>" name="<?=$name?>" type="<?=$type?>" value="<?=ota_escape($old[$name]??'')?>" <?=$required?'required':''?> maxlength="180"></div><?php endforeach; ?><div class="col-12"><label class="form-label" for="observacoes">Observações para a entrega</label><textarea class="form-control" id="observacoes" name="observacoes" rows="3"><?=ota_escape($old['observacoes']??'')?></textarea></div><div class="col-12"><label class="form-label" for="forma_pagamento">Forma de pagamento *</label><select class="form-select" id="forma_pagamento" name="forma_pagamento" required><option value="">Selecione...</option><?php foreach(['Pix','Dinheiro','Cartão na entrega'] as $f): ?><option value="<?=ota_escape($f)?>" <?=($old['forma_pagamento']??'')===$f?'selected':''?>><?=ota_escape($f)?></option><?php endforeach; ?></select></div></div><p class="small text-secondary mt-3 mb-0">* Campos obrigatórios. O pagamento online não é processado por este site.</p></section></div><div class="col-lg-4"><section class="panel"><h2 class="h4 fw-bold mb-3">Resumo</h2><?php foreach($items as $p): ?><div class="d-flex justify-content-between gap-3 mb-2"><span><?=ota_escape($p['prod_nome'])?> × <?=$p['quantidade']?></span><strong><?=ota_money($p['subtotal'])?></strong></div><?php endforeach; ?><hr><div class="d-flex justify-content-between"><strong>Total dos produtos</strong><span class="total"><?=ota_money(ota_cart_total($items))?></span></div><p class="small text-secondary mt-3">Entrega a combinar.</p><button class="btnota w-100 mt-2" type="submit">Revisar pedido <i class="bi bi-arrow-right"></i></button></section></div></form></main></body></html>
